using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ── AddItem ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-1", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(2, _cart.Items["SKU-1"].Quantity);
        Assert.AreEqual(9.99m, _cart.Items["SKU-1"].Price);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-1", 2, 5.00m);
        _cart.AddItem("SKU-1", 3, 5.00m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(5, _cart.Items["SKU-1"].Quantity);
    }

    [TestMethod]
    public void AddItem_MultipleSkus_AllTracked()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);

        Assert.HasCount(2, _cart.Items);
        Assert.Contains("A", _cart.Items.Keys);
        Assert.Contains("B", _cart.Items.Keys);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 1m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", qty, 1m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() => _cart.AddItem("X", 1, -5m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _cart.AddItem("FREE", 1, 0m);

        Assert.AreEqual(0m, _cart.Items["FREE"].Price);
    }

    // ── RemoveItem ───────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-1", 1, 10m);

        _cart.RemoveItem("SKU-1");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_Throws()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void RemoveItem_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    [TestMethod]
    public void RemoveItem_OnlyTargetItem_OthersRemain()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 1, 20m);

        _cart.RemoveItem("A");

        Assert.HasCount(1, _cart.Items);
        Assert.Contains("B", _cart.Items.Keys);
    }

    // ── CalculateTotal ───────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsCorrectTotal()
    {
        _cart.AddItem("X", 3, 10m);

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_SumsAll()
    {
        _cart.AddItem("A", 2, 10m);  // 20
        _cart.AddItem("B", 1, 15m);  // 15

        Assert.AreEqual(35m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemove_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.AddItem("B", 1, 50m);
        _cart.RemoveItem("A");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    // ── ApplyCoupon ──────────────────────────────────────────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF", 50)]
    public void ApplyCoupon_ValidCode_SetsDiscount(string code, int expectedPercent)
    {
        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedPercent, _cart.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Accepted()
    {
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(10m, _cart.DiscountPercent);
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));

        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ApplyCoupon_NullOrEmpty_Throws(string? code)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedByNewCoupon()
    {
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(20m, _cart.DiscountPercent);
    }

    // ── CalculateTotal + Coupon (integration) ────────────────

    [TestMethod]
    public void CalculateTotal_WithCoupon_AppliesDiscount()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.ApplyCoupon("SAVE10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_HalfCoupon_HalvesTotal()
    {
        _cart.AddItem("A", 2, 50m);  // subtotal 100
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CouponOnEmptyCart_ReturnsZero()
    {
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(0m, _cart.CalculateTotal());
    }
}

